//! Native modules generated by Cargo from the current platform API declarations.
#[allow(
    clippy::redundant_closure_call,
    clippy::needless_borrow,
    // The singleton walk is the same shape as every other: a list it pushes to.
    clippy::vec_init_then_push,
    // An absorbed column is `Ok(<its read>)` whatever the read is; where the
    // read is one call, its `?` and the `Ok` cancel.
    clippy::needless_question_mark
)]
#[rustfmt::skip]
pub mod facade {
    include!(concat!(env!("OUT_DIR"), "/src/generated/facade.rs"));
}
#[rustfmt::skip]
pub mod object {
    include!(concat!(env!("OUT_DIR"), "/src/generated/object.rs"));
}
